   where t.source_kind = 'java_tutorial' and t.source_ref in ('collections-framework/linkedlist', 'collections-framework/hashset', 'collections-framework/treemap', 'collections-framework/treeset', 'collections-framework/iterator', 'collections-framework/comparable', 'collections-framework/comparator', 'advanced-java/generics', 'advanced-java/wrapper-classes', 'advanced-java/enum', 'object-oriented-programming/access-modifiers', 'object-oriented-programming/encapsulation', 'object-oriented-programming/final-keyword', 'object-oriented-programming/super-keyword', 'arrays-and-strings/stringbuilder', 'arrays-and-strings/string-pool', 'multithreading/synchronization', 'multithreading/executor-framework', 'jvm-internals-and-memory/garbage-collection', 'file-handling-and-jdbc/jdbc')
     and c.metadata ->> 'source' = 'java_practice_seed' and c.metadata ->> 'origin' = 'java_lesson_rewrite';
  if v_practice <> 20 then raise exception 'validation: expected 20 practice blocks, found %', v_practice; end if;
  select count(*) into v_tests from public.practice_tests where id in ('pt-java-linkedlist', 'pt-java-hashset', 'pt-java-treemap', 'pt-java-treeset', 'pt-java-iterator', 'pt-java-comparable', 'pt-java-comparator', 'pt-java-generics', 'pt-java-wrapper-classes', 'pt-java-enum', 'pt-java-access-modifiers', 'pt-java-encapsulation', 'pt-java-final-keyword', 'pt-java-super-keyword', 'pt-java-stringbuilder', 'pt-java-string-pool', 'pt-java-synchronization', 'pt-java-executor-framework', 'pt-java-garbage-collection', 'pt-java-jdbc') and learning_topic_id is not null;
  if v_tests <> 20 then raise exception 'validation: expected 20 linked mock tests, found %', v_tests; end if;
  select count(*) into v_questions from public.test_questions where test_id in ('pt-java-linkedlist', 'pt-java-hashset', 'pt-java-treemap', 'pt-java-treeset', 'pt-java-iterator', 'pt-java-comparable', 'pt-java-comparator', 'pt-java-generics', 'pt-java-wrapper-classes', 'pt-java-enum', 'pt-java-access-modifiers', 'pt-java-encapsulation', 'pt-java-final-keyword', 'pt-java-super-keyword', 'pt-java-stringbuilder', 'pt-java-string-pool', 'pt-java-synchronization', 'pt-java-executor-framework', 'pt-java-garbage-collection', 'pt-java-jdbc');
  if v_questions <> 200 then raise exception 'validation: expected 200 MCQs, found %', v_questions; end if;
  raise notice '0146/117 OK: Java Tutorials rewrite batch 02: % lessons, % practice blocks, % tests, % MCQs.',
    v_bodies, v_practice, v_tests, v_questions;
end
$val$;

notify pgrst, 'reload schema';
